//! Whole immutable-original lifecycle comparisons; finite DATA cannot mint EOF.
use crate::lint::Registry;
#[path="../fixtures/original_policies/lifecycle.rs"]mod original;
#[path="../fixtures/native-lifecycle/fixture.rs"]mod fixture;
fn record(outcome:&crate::run::Outcome)->serde_json::Value{serde_json::json!({"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text})}
#[test]fn unique_lifecycle_preserves_full_original_ancestor_false_clean_pattern_order_config_counts_and_report(){for case in fixture::CASES{let root=crate::test_scratch::dir(&format!("lifecycle-original-{case}"));for(relative,text)in fixture::files(case).unwrap(){let file=root.join(relative);std::fs::create_dir_all(file.parent().unwrap()).unwrap();std::fs::write(file,text).unwrap();}let options=crate::run::Options{root:root.clone(),lints:vec!["lifecycle".into()],raw:true,no_cache:true,..Default::default()};let mut registry=Registry::default();original::register(&mut registry);let old=crate::run::Engine::new(registry,options.clone()).unwrap();let current=crate::run::Engine::new(crate::run::registry(),options).unwrap();let expected=old.run_one(old.reg.lints[0].as_ref());let actual=current.run_one(current.reg.lints.iter().find(|lint|lint.meta().name=="lifecycle").unwrap().as_ref());assert_eq!(record(&actual),record(&expected),"entire original lifecycle report {case}");assert!(!expected.run.notes.is_empty());assert!(expected.allow_used.is_empty());if *case=="pattern_order_config"{assert_eq!(expected.run.sites.iter().take(4).map(|site|site.rule.as_str()).collect::<Vec<_>>(),vec!["global_list_write","processing_start","global_signal_registration","radio_join"]);assert!(expected.run.sites.iter().all(|site|site.rel!="code/exempt.dm"));}println!("LIFECYCLE_WHOLE_ORIGINAL={}",serde_json::json!({"case":case,"record":record(&actual)}));}}
#[cfg(feature="native-policy")]
struct Pages<'a>{root:&'a std::path::Path,rows:Vec<(String,dm_preprocess::SourceText)>,budget:std::sync::Arc<crate::captured_generator_budget::Budget>,config:crate::captured_raw_file::Config,pass:std::cell::Cell<usize>}
#[cfg(feature="native-policy")]
impl crate::reactive_raw_policy_pages::RawPolicyPages for Pages<'_>{fn for_each(&self,visit:&mut dyn FnMut(&str,crate::captured_raw_file::RawPolicyViews<'_>)->Result<bool,crate::captured_reactive_reads::Failure>)->Result<bool,crate::captured_reactive_reads::Failure>{let pass=self.pass.get();self.pass.set(pass+1);for(relative,text)in &self.rows{if pass==1&&self.config.policy_path_exempt("lifecycle","",relative){continue}if !crate::captured_raw_file::with_original_policy_file(self.root,&self.root.join(relative),text.clone(),0,&self.budget,visit)?{return Ok(false)}}Ok(true)}}
#[cfg(feature="native-policy")]
#[test]fn native_lifecycle_data_matches_frozen_original_on_actual_bytes_without_workspace_authority(){use crate::{captured_generator_budget::Budget,captured_raw_policy::Configuration};for case in fixture::CASES{let root=crate::test_scratch::dir(&format!("lifecycle-native-data-{case}"));let files=fixture::files(case).unwrap();for(relative,text)in &files{let file=root.join(relative);std::fs::create_dir_all(file.parent().unwrap()).unwrap();std::fs::write(file,text).unwrap();}let options=crate::run::Options{root:root.clone(),lints:vec!["lifecycle".into()],raw:true,no_cache:true,..Default::default()};let mut registry=Registry::default();original::register(&mut registry);let old=crate::run::Engine::new(registry,options).unwrap();let expected=old.run_one(old.reg.lints[0].as_ref());let budget=Budget::new(32*1024*1024).unwrap();let mut rows=Vec::new();for(relative,text)in &files{if !crate::tree::CODE_DM.matches_path(relative){continue}let acquired=dm_preprocess::AcquiredSource::from_original_bytes(text.as_bytes().to_vec(),());rows.push((relative.to_string(),acquired.lease().source_text().clone()));}rows.sort_by(|a,b|a.0.cmp(&b.0));let config=files.iter().find(|(relative,_)|*relative=="tools/ci/lint_scopes.toml").unwrap().1;let pages=Pages{root:&root,rows,budget:budget.clone(),config:crate::captured_raw_file::Config::capture(Configuration::Captured(config.as_bytes())).unwrap(),pass:std::cell::Cell::new(0)};let actual=crate::captured_lifecycle_pages::collect_from_pages(&pages,&budget,&||Ok(())).unwrap();assert_eq!(actual.sites(),expected.run.sites.as_slice(),"entire native/original sites/order {case}");assert_eq!(actual.notes(),expected.run.notes.as_slice(),"entire native/original counts {case}");assert_eq!(pages.pass.get(),2);let fresh=Budget::new(32*1024*1024).unwrap();assert!(matches!(crate::captured_lifecycle_pages::collect_from_pages(&pages,&fresh,&||Err(std::io::Error::from_raw_os_error(1450))),Err(crate::captured_reactive_reads::Failure::Operational(ref e))if e.raw_os_error()==Some(1450)));}}
